package handlers

func init() {
	adminTemplates["static_delivery"] = adminLayoutStart + staticDeliveryBody + adminLayoutEnd
}

const staticDeliveryBody = `
<div class="page-header"><h1>Cloudflare 账号与发布目标</h1><p>管理报告静态页面的独立发布地址。这里的操作不会更改原有内容发布方式。</p><a class="btn btn-secondary" href="/cm/static-delivery/publish">报告导出与发布记录</a></div>
<style>.delivery{max-width:1120px}.delivery section{margin:32px 0}.delivery .card{padding:24px}.delivery form{margin:16px 0}.delivery label{display:block;margin:12px 0 6px}.delivery input,.delivery select{max-width:100%;width:100%;padding:10px 12px;min-height:44px;background:var(--bg);color:var(--text);border:1px solid var(--border);border-radius:6px}.delivery .fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:8px 24px}.delivery .actions{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.delivery .actions form{margin:0}.delivery button{min-height:44px}.delivery p{max-width:76ch;line-height:1.65;overflow-wrap:anywhere}.delivery summary{cursor:pointer;padding:12px 0}.delivery .subtle{color:var(--text-muted)}.delivery .entry{border-bottom:1px solid var(--border);padding:20px 0}.delivery :focus-visible{outline:2px solid var(--primary);outline-offset:3px}.delivery small{display:block;margin:8px 0;line-height:1.6}.delivery .account-id{font-size:14px;overflow-wrap:anywhere}.delivery input[type=checkbox]{width:20px;min-height:20px;vertical-align:middle}@media(max-width:600px){.delivery .card{padding:16px}.delivery .actions{align-items:stretch}.delivery .actions button{width:100%}.delivery .actions form{flex:1 1 140px}}</style>
<div class="delivery">
{{if .Saved}}<div class="card" role="status">操作已保存。</div>{{end}}
{{if .Notice}}<div class="card" role="alert">{{.Notice}}</div>{{end}}
{{if .ModuleError}}<div class="card" role="alert">{{.ModuleError}}</div>{{else}}
<div class="card" role="status"><p>无需配置服务器加密密钥。API Token 以明文保存在数据库中，保存后不在页面回显；数据库备份也会包含 Token。</p></div>
<section aria-labelledby="delivery-accounts"><h2 id="delivery-accounts">Cloudflare 账号</h2><p class="subtle">每个 Cloudflare Account ID 单独管理。Token 只用于该账号，保存后不再显示。</p>
<div class="card">{{range .Accounts}}<article class="entry"><h3>{{.Name}}</h3><p class="account-id">Account ID：{{.AccountID}}</p><p>状态：{{.Status}} · 凭证版本：{{.CredentialRevision}}</p><p>{{if .Verification.Readable}}账号读取已验证{{else}}账号读取尚未验证{{end}}；{{if .Verification.WriteVerified}}已完成部署写入验证{{else}}部署写入尚未验证{{end}}</p>
<div class="actions">{{if eq .Status "archived"}}<form method="post" action="/cm/static-delivery/accounts/{{.ID.Hex}}/restore">{{$.CSRFField}}<button class="btn btn-secondary">恢复为停用</button></form>{{else}}
<form method="post" action="/cm/static-delivery/accounts/{{.ID.Hex}}/verify">{{$.CSRFField}}<button class="btn btn-secondary">检查账号连接</button></form>
{{if eq .Status "enabled"}}<form method="post" action="/cm/static-delivery/accounts/{{.ID.Hex}}/disable">{{$.CSRFField}}<button class="btn btn-secondary">停用账号</button></form>{{else}}<form method="post" action="/cm/static-delivery/accounts/{{.ID.Hex}}/enable">{{$.CSRFField}}<button class="btn btn-secondary">启用账号</button></form>{{end}}
<form method="post" action="/cm/static-delivery/accounts/{{.ID.Hex}}/archive">{{$.CSRFField}}<button class="btn btn-secondary">归档账号</button></form>{{end}}</div>
{{if ne .Status "archived"}}<details><summary>轮换 Token 或核实仅授权单个 Worker 的账号</summary><form method="post" action="/cm/static-delivery/accounts/{{.ID.Hex}}/rotate">{{$.CSRFField}}<div class="fields"><div><label for="token-{{.ID.Hex}}">新的 API Token</label><input id="token-{{.ID.Hex}}" type="password" name="token" autocomplete="new-password" required></div><div><label for="worker-{{.ID.Hex}}">指定 Worker（可选）</label><input id="worker-{{.ID.Hex}}" name="worker_name" placeholder="仅有单个 Worker 权限时填写"></div></div><small>先验证新 Token，再切换凭证版本。已排队任务仍使用原版本。</small><button class="btn btn-primary">验证并轮换 Token</button></form>
<form method="post" action="/cm/static-delivery/accounts/{{.ID.Hex}}/verify">{{$.CSRFField}}<label for="scope-{{.ID.Hex}}">验证现有 Token 的指定 Worker</label><input id="scope-{{.ID.Hex}}" name="worker_name" required><button class="btn btn-secondary">检查指定 Worker</button></form></details>{{end}}</article>{{else}}<p>尚未添加账号。先添加一个 Cloudflare Account ID 和对应的 API Token。</p>{{end}}
<details {{if not .Accounts}}open{{end}}><summary>添加 Cloudflare 账号</summary><form method="post" action="/cm/static-delivery/accounts">{{.CSRFField}}<div class="fields"><div><label for="account-name">账号名称</label><input id="account-name" name="name" required maxlength="200" placeholder="例如：测试账号"></div><div><label for="account-id">Cloudflare Account ID</label><input id="account-id" name="account_id" pattern="[a-fA-F0-9]{32}" required autocomplete="off"></div><div><label for="account-token">API Token</label><input id="account-token" type="password" name="token" required autocomplete="new-password"></div><div><label for="account-remark">备注</label><input id="account-remark" name="remark"></div></div><small>使用限定到本账号的 Workers Scripts Edit Token。不要填写 Cloudflare 登录密码或 Global API Key。</small><button class="btn btn-primary">保存账号</button></form></details></div></section>
<section aria-labelledby="delivery-targets"><h2 id="delivery-targets">Worker 发布目标</h2><p class="subtle">每个目标对应一个专用 Worker。停用或归档只影响本地管理，不删除远端 Worker，也不会下线已发布页面。</p><div class="card">
{{range .Targets}}<article class="entry"><h3>{{.Name}}</h3><p>{{.WorkerName}} · {{.Environment}} · {{.Status}}</p><p class="account-id">所属账号记录：{{.AccountRef.Hex}}</p>{{if .Origin}}<p>公开地址：<a href="{{.Origin}}" target="_blank" rel="noopener noreferrer">{{.Origin}}</a></p>{{end}}<p>站点版本：{{.CurrentRevision}}</p>
<div class="actions">{{if eq .Status "archived"}}<form method="post" action="/cm/static-delivery/targets/{{.ID.Hex}}/restore">{{$.CSRFField}}<button class="btn btn-secondary">恢复为停用</button></form>{{else}}
{{if or (eq .Status "draft") (eq .Status "initializing")}}<form method="post" action="/cm/static-delivery/targets/{{.ID.Hex}}/initialize">{{$.CSRFField}}<label><input type="checkbox" name="confirm_initialize" value="yes" required> 确认只创建本系统专用 Worker，不接管现有站点</label><button class="btn btn-primary">{{if eq .Status "initializing"}}核实初始化结果{{else}}初始化专用 Worker{{end}}</button></form>{{else}}<form method="post" action="/cm/static-delivery/targets/{{.ID.Hex}}/verify">{{$.CSRFField}}<button class="btn btn-secondary">核实 Worker 与公开地址</button></form>
{{if eq .Status "disabled"}}<form method="post" action="/cm/static-delivery/targets/{{.ID.Hex}}/enable">{{$.CSRFField}}<button class="btn btn-secondary">核实并启用</button></form>{{else}}<form method="post" action="/cm/static-delivery/targets/{{.ID.Hex}}/disable">{{$.CSRFField}}<button class="btn btn-secondary">停用目标</button></form>{{end}}{{end}}
<form method="post" action="/cm/static-delivery/targets/{{.ID.Hex}}/archive">{{$.CSRFField}}<button class="btn btn-secondary">归档目标</button></form>{{end}}</div></article>{{else}}<p>尚未设置发布目标。添加账号并检查连接后，再创建专用 Worker 目标。</p>{{end}}
{{if .Accounts}}<details><summary>添加 Worker 目标</summary><form method="post" action="/cm/static-delivery/targets">{{.CSRFField}}<div class="fields"><div><label for="target-account">所属账号</label><select id="target-account" name="account_ref" required><option value="">选择账号</option>{{range .Accounts}}{{if eq .Status "enabled"}}<option value="{{.ID.Hex}}">{{.Name}}（{{.AccountID}}）</option>{{end}}{{end}}</select></div><div><label for="target-name">目标名称</label><input id="target-name" name="name" required maxlength="200"></div><div><label for="target-worker">Worker 名称</label><input id="target-worker" name="worker_name" required pattern="[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?" placeholder="例如：reports-test"></div><div><label for="target-env">目标环境</label><select id="target-env" name="environment"><option value="test">测试（不允许搜索引擎收录）</option><option value="production">生产</option></select></div><div><label for="target-origin">公开 HTTPS 地址（可选）</label><input id="target-origin" name="public_origin" type="url" placeholder="留空则使用真实的 workers.dev 地址"></div></div><small>保存目标不会立即创建或覆盖远端 Worker。自定义域名需先在 Cloudflare 控制台配置。</small><button class="btn btn-primary">保存目标</button></form></details>{{end}}</div></section>
{{end}}</div>`
